        plan("The Rules and their notification identity", [10], "A compliance claim must cite the rule and the date rather than the statute alone.", "Ground a rules-based obligation in its exact notification instead of a general reference."),
        plan("Two subsections that are routinely swapped", [11], "The transparency amendment is already operative and the technology-statute amendment is deferred, and the pending challenge has no stated outcome.", "Avoid the single most common current-status error in a transparency or data-protection answer."),
        plan("Enacted categories that are not yet enforceable", [12], "A right on the statute book must not be presented as an enforceable right today.", "Use the statutory vocabulary correctly while keeping the commencement position explicit."),
        plan("Two consent managers that are not the same registration", [13], "One is general-purpose under the Rules and the other is finance-specific under the regulator, with different commencement.", "Separate two consent constructs that a close-option demand deliberately confuses."),
        plan("The Board and the five-stage enforcement sequence", [14], "Establishment is not appointment, and appointment is not adjudication.", "State where an enforcement institution actually stands before assessing whether protection is real."),
        plan("Authentication dependency and the reuse tension", [15, 16], "An offline override mitigates exclusion and reintroduces discretion, and consent fatigue defeats a sound architecture.", "Trace efficiency at the median and denial at the tail as one causal chain rather than two claims."),
